import io


def export_rows(rows, columns):
    out = io.StringIO()
    out.write(','.join(columns) + '\n')
    for row in rows:
        out.write(','.join(str(row[c]) for c in columns) + '\n')
    return out.getvalue()


def parse_rows(text):
    lines = text.strip().split('\n')
    header = lines[0].split(',')
    return [dict(zip(header, line.split(','))) for line in lines[1:]]

