import csv
import io


def export_rows(rows, columns):
    out = io.StringIO()
    writer = csv.DictWriter(out, fieldnames=columns, extrasaction='ignore', lineterminator='\n')
    writer.writeheader()
    for row in rows:
        writer.writerow({c: row[c] for c in columns})
    return out.getvalue()


def parse_rows(text):
    return list(csv.DictReader(io.StringIO(text)))

